mapper.select:
SELECT id, user_id, token_hash, expires_at, created_at, revoked_at
FROM refresh_tokens
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE token_hash = #{tokenHash}
  AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL
